import{_ as s,o as a,c as t,ao as e}from"./chunks/framework.CGAfXaNK.js";const c=JSON.parse('{"title":"2D plots","description":"","frontmatter":{},"headers":[],"relativePath":"visualisation/2d.md","filePath":"visualisation/2d.md","lastUpdated":null}'),l={name:"visualisation/2d.md"};function n(o,i,h,d,p,r){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="2D-plots" tabindex="-1">2D plots <a class="header-anchor" href="#2D-plots" aria-label="Permalink to &quot;2D plots {#2D-plots}&quot;">​</a></h1><p>The 2D plots show resistivity sections, the mesh, and the apparent resistivity and phase at each station. They are written as PNG files and need no display, so they also work in batch jobs.</p><h2 id="Plot-an-inversion" tabindex="-1">Plot an inversion <a class="header-anchor" href="#Plot-an-inversion" aria-label="Permalink to &quot;Plot an inversion {#Plot-an-inversion}&quot;">​</a></h2><p>After a <a href="./../inversion/2d_deterministic">deterministic</a> or <a href="./../inversion/2d_vfsa">VFSA</a> inversion, one call writes all the standard plots into the run&#39;s <code>plots/</code> folder:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotInversion2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run; true_model_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;model.true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, maximum_depth_km </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>You get the mesh, the start and final models, the data fit and the convergence. A VFSA run adds the median, best, 5 %, 95 % and standard deviation models of the ensemble.</p><h2 id="Plot-a-model-file" tabindex="-1">Plot a model file <a class="header-anchor" href="#Plot-a-model-file" aria-label="Permalink to &quot;Plot a model file {#Plot-a-model-file}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotModel2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; output_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Model.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, maximum_depth_km </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, show_padding </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li><p><code>maximum_depth_km</code> cuts the section at that depth.</p></li><li><p><code>show_padding = false</code> shows only the core of the mesh, under the stations.</p></li><li><p><code>resistivity_log10_range</code> sets the colour scale, <code>(0.0, 4.0)</code> by default (1 to 10 000 Ω·m).</p></li></ul><h2 id="Plot-data" tabindex="-1">Plot data <a class="header-anchor" href="#Plot-data" aria-label="Permalink to &quot;Plot data {#Plot-data}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotData2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; output_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Data.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotData2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; predicted_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data.pred&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, output_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;DataFit.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The first line plots the observed TE and TM curves of every station. With <code>predicted_path</code> the predicted curves are drawn on top, so you can see where the model fits and where it does not. Use <code>station_indices = 1:5</code> to plot only some stations.</p><h2 id="Build-your-own-figure" tabindex="-1">Build your own figure <a class="header-anchor" href="#Build-your-own-figure" aria-label="Permalink to &quot;Build your own figure {#Build-your-own-figure}&quot;">​</a></h2><p>For figures that are not covered above, use the building blocks that work on a mesh and a resistivity array in memory: <code>plot_mt2d_model</code>, <code>plot_mt2d_mesh</code>, <code>plot_mt2d_data_fit</code>, <code>plot_mt2d_site_curves</code> and the convergence plots <code>plot_inv2d_convergence</code> and <code>plot_vfsa2d_convergence</code>. They take the same keywords as the functions above.</p>`,14)])])}const u=s(l,[["render",n]]);export{c as __pageData,u as default};
